package com.emssystem.emsleaveservice.pto.entity; import com.emssystem.emsleaveservice.pto.enums.PtoRequestStatus; import com.emssystem.emsleaveservice.shared.entity.AuditableEntity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="pto_requests",indexes={@Index(name="idx_pto_request_employee_dates",columnList="employee_id,start_date,end_date"),@Index(name="idx_pto_request_status",columnList="status")}) public class PtoRequest extends AuditableEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="employee_id",nullable=false) private Long employeeId;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="pto_type_id",nullable=false) private PtoType ptoType;@Column(name="start_date",nullable=false) private LocalDate startDate;@Column(name="end_date",nullable=false) private LocalDate endDate;@Column(nullable=false,precision=10,scale=2) private BigDecimal hours;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private PtoRequestStatus status=PtoRequestStatus.PENDING;@Column(name="reviewed_by") private UUID reviewedBy;@Column(name="reviewed_at") private Instant reviewedAt;protected PtoRequest(){}public PtoRequest(Long employeeId,PtoType type,LocalDate start,LocalDate end,BigDecimal hours){this.employeeId=employeeId;this.ptoType=type;this.startDate=start;this.endDate=end;this.hours=hours;}public Long getId(){return id;}public Long getEmployeeId(){return employeeId;}public PtoType getPtoType(){return ptoType;}public LocalDate getStartDate(){return startDate;}public LocalDate getEndDate(){return endDate;}public BigDecimal getHours(){return hours;}public PtoRequestStatus getStatus(){return status;}public UUID getReviewedBy(){return reviewedBy;}public Instant getReviewedAt(){return reviewedAt;}}
